// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant DEPOSITOR = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new C(); }

    function testFuzz_property(
        uint64 numberArg,
        uint64 timestampArg,
        uint256 basefeeArg,
        bytes32 hashArg,
        uint64 sequenceArg,
        bytes32 batcherHashArg,
        uint256 overheadArg,
        uint256 scalarArg
    ) public {
        // keep the two deciding values apart so the rule is exercised, but stay wide
        vm.assume(numberArg != sequenceArg);

        vm.prank(DEPOSITOR);
        c.setL1BlockValues(
            numberArg,
            timestampArg,
            basefeeArg,
            hashArg,
            sequenceArg,
            batcherHashArg,
            overheadArg,
            scalarArg
        );

        // General rule: number and sequenceNumber are stored from their OWN parameters;
        // they must differ whenever the supplied arguments differ.
        assertTrue(c.number() != c.sequenceNumber());
    }
}

