// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new C(); }

    function testFuzz_property(
        uint64 number_,
        uint64 ts1,
        uint64 ts2,
        uint256 basefee_,
        bytes32 hash_,
        uint64 seq_,
        bytes32 batcher_,
        uint256 overhead_,
        uint256 scalar_
    ) public {
        // timestamps must be valid uint64 values (they already are) and must differ
        // so that "latest call wins" is distinguishable from "first call sticks".
        vm.assume(ts1 != ts2);

        vm.startPrank(depositor);
        c.setL1BlockValues(number_, ts1, basefee_, hash_, seq_, batcher_, overhead_, scalar_);
        // sanity of the rule on the first call: timestamp must be ts1 for both versions
        c.setL1BlockValues(number_, ts2, basefee_, hash_, seq_, batcher_, overhead_, scalar_);
        vm.stopPrank();

        // General rule: after any sequence of successful setL1BlockValues calls,
        // c.timestamp() equals the _timestamp of the MOST RECENT successful call.
        assertTrue(c.timestamp() == ts2);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) external {
        bytes memory data = abi.encodeWithSelector(
            c.setL1BlockValues.selector,
            _number, _timestamp, _basefee, _hash,
            _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar
        );
        bool ok;
        (ok, ) = address(c).call(data);
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

