contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint64 number, uint64 timestamp, uint256 basefee, bytes32 hash, uint64 sequenceNumber, bytes32 batcherHash, uint256 l1FeeOverhead, uint256 l1FeeScalar) public payable {
        require(true);
        bool reverted;
        try c.setL1BlockValues(number, timestamp, basefee, hash, sequenceNumber, batcherHash, l1FeeOverhead, l1FeeScalar) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
